async function getMetricSuggestionsService(args) {
  // 根据当前连接的表结构推荐指标
  const configs = await ensureLoaded()
  const connectionId = args && typeof args.connectionId === 'string' ? args.connectionId : ''
  const cfg = configs.connections.find(c => c.id === connectionId)
  if (!cfg) return { ok: false, error: '连接不存在' }
  const got = await getPool(configs, connectionId)
  if (got.error !== undefined) return { ok: false, error: got.error }

  try {
    const schemaResult = await getSchemaInfo(got.pool, cfg.tables)
    if (!schemaResult.ok) return { ok: false, error: schemaResult.error }
    // 智能推荐：找到可能的数值列作为指标候选
    const suggestions = []
    for (const table of schemaResult.schema) {
      for (const col of table.columns) {
        if (/\b(int|bigint|decimal|float|double|numeric|real)\b/i.test(col.type) && !/tinyint\(1\)/i.test(col.type)) {
          const snakeToCamel = (s) => s.replace(/_([a-z])/g, (_, c) => c.toUpperCase())
          suggestions.push({
            name: snakeToCamel(col.column),
            expression: 'SUM(`' + table.name + '`.`' + col.column + '`)',
            sourceTable: table.name,
            sourceColumn: col.column,
            type: 'sum',
            description: (table.comment || table.name) + '.' + (col.comment || col.column) + ' 求和',
          })
        }
      }
    }
    return { ok: true, suggestions: suggestions.slice(0, 50) }
  } catch (err) {
    return { ok: false, error: String(err.message || err) }
  }
}

