async function getDrillDownService(args) {
  const baseQuery = args && typeof args.baseQuery === 'string' ? args.baseQuery : ''
  const dimension = args && typeof args.dimension === 'string' ? args.dimension : ''
  const value = args && args.value !== undefined ? args.value : ''
  if (!baseQuery || !dimension) return { ok: false, error: '缺少查询或维度' }

  const drillSql = dashboard.buildDrillDownQuery(baseQuery, dimension, value)

  // 执行下钻查询
  const configs = await ensureLoaded()
  const sessionId = args && typeof args.sessionId === 'string' ? args.sessionId : undefined
  const connection = resolveSelection(configs, sessionId)
  if (!connection) return { ok: false, error: '未选择数据库连接' }
  const got = await getPool(configs, connection.id)
  if (got.error !== undefined) return { ok: false, error: got.error }

  try {
    const validation = validateAndPrepare(drillSql, { allowlist: connection.tables, maxRows: MAX_ROWS })
    if (!validation.ok) return { ok: false, error: validation.error }
    const [rows, fields] = await got.pool.query(validation.safeSql)
    const columns = Array.isArray(fields) ? fields.map(f => f.name) : []
    const list = Array.isArray(rows) ? rows.slice(0, MAX_ROWS).map(jsonSafe) : []
    const chart = suggestChartForResult({ columns, rows: list }, dimension + ' 下钻')
    return sanitizeForBoundary({ ok: true, sql: validation.safeSql, result: { columns, rows: list, rowCount: list.length }, chart: chart.ok ? chart.spec : null })
  } catch (err) {
    return { ok: false, error: String(err.message || err) }
  }
}

